/**
 * Session rows for the cookie-based auth: create, look up by token hash, revoke.
 */
import { eq, lt } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, sessions, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId, brandStamp } from "./_mappers";
import type {
  IsoTimestamp,
  OrgId,
  SessionId,
  UserId,
} from "@/types/common";
import type { SessionPrincipal } from "@/types/member";

/**
 * Sessions are global rather than tenant-scoped: one cookie can move between
 * organizations via `activeOrgId`, and `SessionService` resolves the `Actor`
 * for whichever org the request addresses.
 */
export async function createSession(
  userId: UserId,
  tokenHash: string,
  expiresAt: IsoTimestamp,
): Promise<SessionPrincipal> {
  const stamp = toIsoTimestamp(new Date());
  const user = getDb().select().from(users).where(eq(users.id, userId)).get();
  if (!user) throw new Error(`User ${userId} not found`);

  getDb()
    .insert(sessions)
    .values({
      id: newId(),
      userId,
      activeOrgId: null,
      tokenHash,
      expiresAt,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .run();

  return {
    userId,
    email: user.email,
    activeOrgId: null,
    expiresAt,
  };
}

/** Expired rows resolve to `null` rather than being returned and re-checked. */
export async function findSessionByTokenHash(
  tokenHash: string,
): Promise<SessionPrincipal | null> {
  const row = getDb()
    .select({ session: sessions, user: users })
    .from(sessions)
    .innerJoin(users, eq(users.id, sessions.userId))
    .where(eq(sessions.tokenHash, tokenHash))
    .get();

  if (!row) return null;
  if (row.session.expiresAt <= new Date().toISOString()) return null;

  return {
    userId: brandId<UserId>(row.session.userId),
    email: row.user.email,
    activeOrgId:
      row.session.activeOrgId === null
        ? null
        : brandId<OrgId>(row.session.activeOrgId),
    expiresAt: brandStamp(row.session.expiresAt),
  };
}

export async function setActiveOrg(
  sessionId: SessionId,
  orgId: OrgId,
): Promise<void> {
  getDb()
    .update(sessions)
    .set({ activeOrgId: orgId, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(sessions.id, sessionId))
    .run();
}

export async function revokeSession(sessionId: SessionId): Promise<void> {
  getDb().delete(sessions).where(eq(sessions.id, sessionId)).run();
}

/** Housekeeping sweep; returns how many rows the scheduler removed. */
export async function purgeExpiredSessions(
  now: IsoTimestamp,
): Promise<number> {
  const rows = getDb()
    .delete(sessions)
    .where(lt(sessions.expiresAt, now))
    .returning({ id: sessions.id })
    .all();
  return rows.length;
}

/**
 * Denormalised search index kept in step by `SearchService`.
 */
import { and, count, desc, eq, inArray, like } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, searchIndex } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import type { SearchQueryInput } from "@/schemas/search";
import type { SearchIndexRow } from "@/server/db/schema/webhooks";
import type { OrgId, Page, ProjectId } from "@/types/common";

/**
 * Upsert by (org, kind, subject) rather than by row id: the indexer is called
 * on every write and must be idempotent.
 */
export async function upsertSearchDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
  content: string,
  projectId: ProjectId | null,
): Promise<void> {
  const db = getDb();
  const indexedAt = toIsoTimestamp(new Date());

  const existing = db
    .select({ id: searchIndex.id })
    .from(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .get();

  if (existing) {
    db.update(searchIndex)
      .set({ content, projectId, indexedAt })
      .where(eq(searchIndex.id, existing.id))
      .run();
    return;
  }

  db.insert(searchIndex)
    .values({
      id: newId(),
      orgId,
      subjectKind,
      subjectId,
      projectId,
      content,
      indexedAt,
    })
    .run();
}

export async function deleteSearchDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .run();
}

/**
 * Substring match over the denormalised content column. Deliberately simple —
 * the index is a convenience layer, not a search engine, and the tenant filter
 * is what actually matters here.
 */
export async function searchDocuments(
  input: SearchQueryInput,
): Promise<Page<SearchIndexRow>> {
  const db = getDb();
  const sort = { sortColumn: searchIndex.indexedAt, idColumn: searchIndex.id };

  const filters = compact(
    orgPredicate(searchIndex.orgId, input.orgId),
    like(searchIndex.content, `%${input.q}%`),
    input.kinds.length === 0
      ? undefined
      : inArray(searchIndex.subjectKind, [...input.kinds]),
    input.projectId === undefined
      ? undefined
      : eq(searchIndex.projectId, input.projectId),
  );

  const total = db
    .select({ value: count() })
    .from(searchIndex)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(searchIndex)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(searchIndex.indexedAt), desc(searchIndex.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => row,
    (row) => ({ id: row.id, sortValue: row.indexedAt }),
  );
}

/** Drift alarm input: how many documents this org currently has indexed. */
export async function countIndexed(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(searchIndex)
    .where(orgPredicate(searchIndex.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

export type SearchSubjectKind = 'issue' | 'comment' | 'project';

