/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug. The workspace is kept,
 * inert, for `DELETED_WORKSPACE_RETENTION_DAYS` — its owner can restore it
 * until then, and the retention sweep purges it once the window closes.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  assertNotArchived("Organization", org.id, org);

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  const archived = await orgRepo.archiveOrg(input.orgId);

  await emit("organization.deleted", {
    ...actorEnvelope(actor),
    slug: archived.slug,
  });

  return archived;
}

/**
 * Restores a workspace inside its `DELETED_WORKSPACE_RETENTION_DAYS` grace
 * period. No `Actor` can be resolved for a deleted workspace — sign-in and the
 * org switcher both hide it — so the caller is identified by bare `userId`,
 * and the actor is assembled here from the membership row the deletion left
 * untouched.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);

  const member = await memberRepo.findMember(orgId, userId);
  if (member === null) {
    throw new NotFoundError("Organization", orgId);
  }

  if (org.archivedAt === null) {
    return org;
  }

  const deadline =
    new Date(org.archivedAt).getTime() +
    DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;
  if (Date.now() >= deadline) {
    throw new NotFoundError("Organization", orgId);
  }

  assertCan({ userId, orgId, role: member.role }, "org:restore", orgResource(orgId));

  const restored = await orgRepo.restoreOrg(orgId);

  await emit("organization.restored", {
    ...envelope(orgId, userId),
    slug: restored.slug,
  });

  return restored;
}

