import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);

import { DELETED_WORKSPACE_RETENTION_DAYS } from "@/config/constants";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { NotFoundError } from "@/server/services/_support";
import * as invitationService from "@/server/services/invitation-service";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import { runWebhookDeliveryJob } from "@/server/jobs/webhook-delivery-job";
import * as notificationService from "@/server/services/notification-service";
import {
  deleteOrganization,
  restoreOrganization,
} from "@/server/services/organization-service";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("scratch: delete/restore lifecycle", () => {
  it("full grace-period lifecycle", async () => {
    const tenant: Tenant = await createTenant("grace");
    await usageRepo.recomputeUsage(tenant.org.id);

    // pending invitation before delete
    const invitation = await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: "pending@grace.test", role: "member", expiresInDays: 14 },
      tenant.userIds.owner,
      "tokenhash-grace",
    );

    const deleted = await deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });
    expect(deleted.archivedAt).not.toBeNull();

    // double delete -> AlreadyArchivedError
    await expect(
      deleteOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        confirmSlug: tenant.org.slug,
      }),
    ).rejects.toThrow(AlreadyArchivedError);

    // sign-in / listing hidden
    expect(await orgRepo.findOrgBySlug(tenant.org.slug)).toBeNull();
    const listed = await orgRepo.listOrgsForUser(tenant.userIds.owner);
    expect(listed.find((o) => o.id === tenant.org.id)).toBeUndefined();

    // notify() creates nothing
    const notified = await notificationService.notify(
      tenant.org.id,
      "comment_created",
      [tenant.userIds.member],
      { title: "t", body: "b", href: "/x", actorId: null },
    );
    expect(notified).toEqual([]);

    // invitation acceptance throws NotFoundError, stays pending
    await expect(
      invitationService.acceptInvitation(tenant.userIds.admin, {
        token: "tokenhash-grace",
      }),
    ).rejects.toThrow(NotFoundError);
    const stillPending = await invitationRepo.listPendingInvitations(tenant.org.id);
    expect(stillPending.some((i) => i.id === invitation.id)).toBe(true);

    // jobs leave it alone
    const rollupIds = await usageRepo.listOrgIdsForRollup(1000);
    expect(rollupIds).not.toContain(tenant.org.id);

    const overdueResult = await runOverdueIssueJob(new Date());
    expect(overdueResult.failed).toBe(0);

    const usageBefore = await usageRepo.getUsage(tenant.org.id);
    await runUsageRollupJob(new Date());
    const usageAfter = await usageRepo.getUsage(tenant.org.id);
    expect(usageAfter.measuredAt).toBe(usageBefore.measuredAt);

    // webhook delivery marked failed, not delivered
    const endpoint = await webhookRepo.insertEndpoint(
      { orgId: tenant.org.id, url: "https://example.test/hook", eventTypes: ["issue.created"] },
      "secret",
    );
    await webhookRepo.enqueueDelivery(tenant.org.id, endpoint.id, "issue.created", "{}");
    await runWebhookDeliveryJob(new Date());
    const endpoints = await webhookRepo.listEndpoints(tenant.org.id);
    expect(endpoints.length).toBe(1);

    // trial expiry does not downgrade
    await subscriptionRepo.updateSubscriptionPlan(tenant.org.id, "starter", "monthly");
    await runTrialExpiryJob(new Date(Date.now() + 400 * 24 * 60 * 60 * 1000));
    const sub = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(sub?.plan).toBe("starter");

    // restore: non-member -> NotFoundError
    const outsider = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    expect(outsider).not.toBeNull();

    // non-owner member -> PermissionDeniedError
    await expect(
      restoreOrganization(tenant.userIds.admin, tenant.org.id),
    ).rejects.toThrow(PermissionDeniedError);

    // owner restores successfully
    const restored = await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect(restored.archivedAt).toBeNull();

    // restoring again (already live) is a no-op
    const restoredAgain = await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect(restoredAgain.archivedAt).toBeNull();

    // things resume: listed again
    const listedAfter = await orgRepo.listOrgsForUser(tenant.userIds.owner);
    expect(listedAfter.find((o) => o.id === tenant.org.id)).toBeDefined();
  });

  it("restore fails once the window has closed; purge removes everything", async () => {
    const tenant: Tenant = await createTenant("purge");
    await usageRepo.recomputeUsage(tenant.org.id);

    await deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    // Manually age the deletion past the retention window.
    const longAgo = new Date(
      Date.now() - (DELETED_WORKSPACE_RETENTION_DAYS + 1) * 24 * 60 * 60 * 1000,
    );
    const db = (await import("@/server/db")).getDb();
    const { organizations } = await import("@/server/db");
    const { eq } = await import("drizzle-orm");
    db.update(organizations)
      .set({ archivedAt: longAgo.toISOString() })
      .where(eq(organizations.id, tenant.org.id))
      .run();

    await expect(
      restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toThrow(NotFoundError);

    const result = await runCleanupArchivedJob(new Date());
    expect(result.failed).toBe(0);

    expect(await orgRepo.findOrgById(tenant.org.id)).toBeNull();
    const members = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    expect(members).toBeNull();

    await expect(
      restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toThrow(NotFoundError);
  });
});

